//! Shared helpers of the vector tests: loading `tests/vectors/*.json` (generated by `cargo xtask gen-pch-data
//! vectors` under the CPython 3.12.3 / 3.13 oracles) and comparing outcomes.
//!
//! Owner: WP-17.

use std::path::PathBuf;

use serde_json::Value;
use snp_pyparsers::CheckError;

/// `tests/vectors/<name>`.
pub(crate) fn vectors(name: &str) -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/vectors")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

/// Standard base64 decoding (the vector files carry raw inputs that way).
pub(crate) fn b64(s: &str) -> Vec<u8> {
    let val = |c: u8| -> u32 {
        match c {
            b'A'..=b'Z' => u32::from(c - b'A'),
            b'a'..=b'z' => u32::from(c - b'a') + 26,
            b'0'..=b'9' => u32::from(c - b'0') + 52,
            b'+' => 62,
            b'/' => 63,
            _ => panic!("bad base64 byte {c}"),
        }
    };
    let mut out = Vec::new();
    let bytes: Vec<u8> = s.bytes().filter(|&c| c != b'=').collect();
    let mut start = 0;
    while start < bytes.len() {
        let chunk = &bytes[start..bytes.len().min(start + 4)];
        let mut acc = 0u32;
        for (i, &c) in chunk.iter().enumerate() {
            acc |= val(c) << (18 - 6 * i);
        }
        let n = chunk.len();
        let all = acc.to_be_bytes();
        out.extend_from_slice(&all[1..n]);
        start += 4;
    }
    out
}

/// `s` repeated `n` times.
pub(crate) fn rep(s: &str, n: usize) -> String {
    std::iter::repeat_n(s, n).collect()
}

/// A case's raw input: `{"b64": …}` or `{"repeat": [b64(unit), count], "tail": b64}` (`pch_vectors.py` `blob`).
pub(crate) fn input(case: &Value) -> Vec<u8> {
    if let Some(s) = case.get("b64") {
        return b64(s.as_str().unwrap());
    }
    let rep = case["repeat"].as_array().unwrap();
    let unit = b64(rep[0].as_str().unwrap());
    let count = usize::try_from(rep[1].as_u64().unwrap()).unwrap();
    let mut out: Vec<u8> = std::iter::repeat_n(unit.as_slice(), count)
        .flatten()
        .copied()
        .collect();
    out.extend(b64(case["tail"].as_str().unwrap()));
    out
}

/// FNV-1a (64 bit) of the UTF-8 bytes as 16 hex digits (`pch_vectors.py` `fnv1a64`).
pub(crate) fn fnv1a64(s: &str) -> String {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in s.bytes() {
        h = (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3);
    }
    format!("{h:016x}")
}

/// Whether `got` is the expected text `key` of `result` (verbatim, or `key_fnv`/`key_len` digests).
pub(crate) fn text_matches(result: &Value, key: &str, got: &str) -> Option<bool> {
    if let Some(s) = result.get(key) {
        return Some(s.as_str() == Some(got));
    }
    let fnv = result.get(format!("{key}_fnv"))?;
    let len = result.get(format!("{key}_len"))?;
    Some(
        fnv.as_str() == Some(&fnv1a64(got))
            && len.as_u64() == u64::try_from(got.chars().count()).ok(),
    )
}

/// The outcome a vector records.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum Want {
    Ok,
    Reported(String),
    Crash(String, String),
}

/// `{"ok": true}` / `{"reported": msg}` / `{"crash": [type, text]}`.
pub(crate) fn want(result: &Value) -> Want {
    if let Some(msg) = result.get("reported") {
        return Want::Reported(msg.as_str().unwrap().to_owned());
    }
    if let Some(c) = result.get("crash") {
        return Want::Crash(
            c[0].as_str().unwrap().to_owned(),
            c[1].as_str().unwrap().to_owned(),
        );
    }
    Want::Ok
}

/// A check result in vector terms.
pub(crate) fn got<T>(r: &Result<T, CheckError>) -> Want {
    match r {
        Ok(_) => Want::Ok,
        Err(CheckError::Reported(m)) => Want::Reported(m.clone()),
        Err(CheckError::Crash(e)) => Want::Crash(
            e.ty.to_string(),
            String::from_utf8_lossy(&e.text).into_owned(),
        ),
        Err(other) => panic!("unknown CheckError {other:?}"),
    }
}

/// Collects mismatches and panics with all of them at the end.
#[derive(Default)]
pub(crate) struct Failures(Vec<String>);

impl Failures {
    pub(crate) fn check(&mut self, name: &str, got: &Want, want: &Want) {
        if got != want {
            self.0
                .push(format!("{name}:\n     got {got:?}\n    want {want:?}"));
        }
    }

    pub(crate) fn push(&mut self, msg: String) {
        self.0.push(msg);
    }

    pub(crate) fn finish(self, what: &str) {
        if !self.0.is_empty() {
            let n = self.0.len();
            let shown: Vec<_> = self.0.into_iter().take(40).collect();
            panic!("{what}: {n} mismatches\n{}", shown.join("\n"));
        }
    }
}
